// KONTROL SENTUH (multi-touch): membaca semua sentuhan, mengecek tombol di layer "Sentuh",
// lalu mengisi variabel scene TKiri, TKanan, TLompat, TTembak, TTurun, TSkill, TGantiSkill, TGanti, TJeda
// (1 = sedang ditekan) dan versi ...Tekan (1 hanya pada frame pertama ditekan).
const im = runtimeScene.getGame().getInputManager();
const vars = runtimeScene.getVariables();
const gv = runtimeScene.getGame().getVariables();
const mode = gv.get('KontrolSentuh').getAsNumber();
let aktif = false;
if (mode === 1) aktif = true;
else if (mode === 0) aktif = (typeof window !== 'undefined') && (('ontouchstart' in window) || ((navigator.maxTouchPoints || 0) > 0));
const jeda = vars.get('Pause').getAsNumber() === 1 || vars.get('GameOver').getAsNumber() === 1;
vars.get('SentuhAktif').setNumber(aktif ? 1 : 0);
const layer = runtimeScene.getLayer('Sentuh');
layer.show(aktif && !jeda);
const peta = {TbKiri: 'TKiri', TbKanan: 'TKanan', TbLompat: 'TLompat', TbTembak: 'TTembak', TbTurun: 'TTurun', TbSkill: 'TSkill', TbGantiSkill: 'TGantiSkill', TbGanti: 'TGanti', TbJeda: 'TJeda'};
const kini = {};
for (const n in peta) kini[peta[n]] = 0;
if (aktif) {
  const ids = im.getAllTouchIdentifiers();
  for (const id of ids) {
    if (im.hasTouchEnded(id)) continue;
    const p = layer.convertCoords(im.getTouchX(id), im.getTouchY(id), 0, [0, 0]);
    for (const n in peta) {
      const objs = runtimeScene.getObjects(n);
      if (!objs) continue;
      for (const o of objs) { if (o.isVisible() && o.insideObject(p[0], p[1])) kini[peta[n]] = 1; }
    }
  }
}
for (const k in kini) {
  const sebelum = vars.get(k).getAsNumber();
  vars.get(k + 'Tekan').setNumber(kini[k] === 1 && sebelum === 0 ? 1 : 0);
  vars.get(k).setNumber(kini[k]);
}
for (const n in peta) { const objs = runtimeScene.getObjects(n); if (objs) for (const o of objs) o.setAnimation(kini[peta[n]]); }
